SELECT time, CAST(metric_0001 AS DOUBLE PRECISION) AS metric_0001, CAST(metric_0112 AS DOUBLE PRECISION) AS metric_0112, CAST(metric_0223 AS DOUBLE PRECISION) AS metric_0223, CAST(metric_0334 AS DOUBLE PRECISION) AS metric_0334, CAST(metric_0445 AS DOUBLE PRECISION) AS metric_0445, CAST(metric_0556 AS DOUBLE PRECISION) AS metric_0556, CAST(metric_0667 AS DOUBLE PRECISION) AS metric_0667, CAST(metric_0778 AS DOUBLE PRECISION) AS metric_0778, CAST(metric_0889 AS DOUBLE PRECISION) AS metric_0889, CAST(metric_1000 AS DOUBLE PRECISION) AS metric_1000 FROM wide1000 WHERE time >= '2024-12-31' AND time < '2025-01-01' ORDER BY time
